(()=>{
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let ready=false,previewIndex=0,previewQuestions=[],busy=false;
 function init(){if(ready||document.body.dataset.questionWorkflow!=='scenario'||!window.ScenarioEditor)return;ready=true;document.body.classList.add('scenario-workspace');
 const grid=document.querySelector('.admin-grid'),shared=$('case-form').closest('section'),editor=$('editor').closest('section');shared.classList.add('shared-editor');editor.classList.add('linked-editor');
 const layout=document.createElement('div');layout.className='scenario-layout';grid.before(layout);layout.innerHTML='<aside class="scenario-library"><h2>Scenarios</h2><button id="new-scenario" class="primary">+ New scenario</button><label>Search scenarios<input id="scenario-search" type="search" placeholder="ID, title or question"></label><label>Subject<select id="scenario-subject"></select></label><label>Topic<select id="scenario-topic"></select></label><div id="scenario-library-list"></div></aside><div id="scenario-main"></div>';
 const main=$('scenario-main');layout.append();main.append(shared);const linked=document.createElement('section');linked.className='linked-sequence';linked.innerHTML='<div class="sequence-heading"><div><h2>2 · Linked questions</h2><p class="hint">Learners follow this order. Use the arrows to reorder.</p></div><button id="scenario-preview" class="secondary">Preview as learner</button></div><div id="scenario-sequence"></div><button id="next-question" class="secondary">+ Add next question</button><p id="sequence-message" role="status"></p><a class="publication-link" href="/cases.html?publication=1">Review publication →</a>';main.append(linked,editor);grid.hidden=true;
 shared.querySelector('h2').textContent='1 · Shared scenario';$('case-select').closest('label').hidden=true;$('case-key').closest('label').classList.add('case-key-label');
 const initial=document.createElement('details');initial.open=true;initial.className='initial-information';initial.innerHTML='<summary>Initial information · shown before question A</summary>';$('case-history').closest('label').before(initial);for(const name of ['history','examination','laboratory'])initial.append($('case-'+name).closest('label'));
 const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Cancel changes';cancel.onclick=()=>ScenarioEditor.cancel();$('save-case').before(cancel);$('save-case').textContent='Save shared scenario';
 const qcancel=cancel.cloneNode(true);qcancel.onclick=()=>QuestionEditor.cancel();$('save').before(qcancel);$('save').textContent='Save question changes';
 $('additional-findings').closest('label').firstChild.textContent='Additional findings · revealed before this question';
 $('new-scenario').onclick=()=>ScenarioEditor.select('');$('next-question').onclick=()=>{$('new').click();editor.scrollIntoView({behavior:'smooth',block:'start'})};
 $('scenario-search').oninput=renderLibrary;$('scenario-subject').onchange=()=>{populateTopics();renderLibrary()};$('scenario-topic').onchange=renderLibrary;
 const dialog=document.createElement('dialog');dialog.id='scenario-preview-dialog';dialog.innerHTML='<div class="sequence-heading"><h2>Scenario preview</h2><button id="close-scenario-preview" class="secondary">Close</button></div><p class="hint">Saved content only · No learner attempt is created.</p><div id="scenario-preview-content"></div><div class="preview-controls"><button id="preview-back" class="secondary">Previous</button><button id="preview-reveal" class="primary">Reveal feedback</button><button id="preview-next" class="secondary">Next question</button></div>';document.body.append(dialog);$('close-scenario-preview').onclick=()=>dialog.close();$('scenario-preview').onclick=()=>{const state=ScenarioEditor.state();if(state.dirty){$('sequence-message').textContent='Save or cancel your edits before previewing.';return;}previewQuestions=state.questions.filter(q=>q.status!=='Archived');if(!previewQuestions.length)return;previewIndex=0;renderPreview();dialog.showModal()};$('preview-back').onclick=()=>{previewIndex--;renderPreview()};$('preview-next').onclick=()=>{previewIndex++;renderPreview()};$('preview-reveal').onclick=()=>{$('preview-explanation').hidden=false;$('preview-next').disabled=previewIndex===previewQuestions.length-1;$('preview-reveal').disabled=true;};
 if(!ScenarioEditor.state().selected&&ScenarioEditor.state().cases.length&&!new URLSearchParams(location.search).has("new"))ScenarioEditor.select(ScenarioEditor.state().cases[0].id);
 update();
 }
 function populateTopics(){const state=ScenarioEditor.state(),subject=$('scenario-subject').value;const old=$('scenario-topic').value;$('scenario-topic').innerHTML='<option value="">All topics</option>'+[...new Set(state.cases.filter(c=>!subject||c.subject===subject).map(c=>c.topic).filter(Boolean))].sort().map(t=>`<option>${esc(t)}</option>`).join('');$('scenario-topic').value=[...$('scenario-topic').options].some(o=>o.value===old)?old:'';}
 function update(){if(!ready)return;const state=ScenarioEditor.state(),old=$('scenario-subject').value;$('scenario-subject').innerHTML='<option value="">All subjects</option>'+[...new Set(state.cases.map(c=>c.subject).filter(Boolean))].sort().map(s=>`<option>${esc(s)}</option>`).join('');$('scenario-subject').value=old;populateTopics();renderLibrary();const active=state.questions.filter(q=>q.status!=='Archived');$('scenario-sequence').innerHTML=state.questions.map(q=>{const i=active.findIndex(x=>x.id===q.id);return `<div class="sequence-row ${state.editing===q.id?'selected':''}"><button class="sequence-open" data-question="${esc(q.id)}"><strong>${esc(state.selected)}${String.fromCharCode(64+q.case_order)}</strong><span>${esc(q.text)}</span><small>${q.additional_findings?'Additional findings before this question':'No additional findings'}</small></button><span class="list-status" data-status="${esc(q.status)}">${esc(q.status)}</span><span>${q.maximum} pt</span><button data-move="-1" data-question="${esc(q.id)}" aria-label="Move ${esc(q.display_code)} up" ${i<=0?'disabled':''}>↑</button><button data-move="1" data-question="${esc(q.id)}" aria-label="Move ${esc(q.display_code)} down" ${i<0||i===active.length-1?'disabled':''}>↓</button></div>`}).join('')||'<p class="hint">Save the shared scenario, then add its first question.</p>';
 $('scenario-sequence').querySelectorAll('.sequence-open').forEach(b=>b.onclick=()=>{ScenarioEditor.edit(b.dataset.question);$('editor').scrollIntoView({behavior:'smooth',block:'start'})});$('scenario-sequence').querySelectorAll('[data-move]').forEach(b=>b.onclick=async()=>{if(busy)return;busy=true;try{const ids=active.map(q=>q.id),i=ids.indexOf(b.dataset.question),j=i+Number(b.dataset.move);[ids[i],ids[j]]=[ids[j],ids[i]];await ScenarioEditor.reorder(ids);$('sequence-message').textContent='Order saved. Backup verified. Previous attempts retain their original sequence.';}catch(e){$('sequence-message').textContent=e.message}finally{busy=false}});
 $('scenario-preview').disabled=!active.length;$('next-question').disabled=!state.selected;
 const draft=active.filter(q=>q.status!=='Published').length;$('scenario-main').querySelector('.publication-link').textContent=(draft?draft+' unreleased question(s) · ':'')+'Review publication →';
 }
 function renderLibrary(){const s=ScenarioEditor.state(),term=$('scenario-search').value.toLowerCase(),subject=$('scenario-subject').value,topic=$('scenario-topic').value;$('scenario-library-list').innerHTML=s.cases.filter(c=>(!subject||c.subject===subject)&&(!topic||c.topic===topic)&&(c.id+' '+c.title).toLowerCase().includes(term)).map(c=>{const qs=s.allQuestions.filter(q=>q.case_id===c.id&&q.status!=='Archived'),status=qs.length&&qs.every(q=>q.status==='Published')?'Published':qs.length&&qs.every(q=>q.status==='Reviewed')?'Reviewed':!qs.length&&s.allQuestions.some(q=>q.case_id===c.id)?'Archived':'Draft';return `<button class="scenario-item ${c.id===s.selected?'selected':''}" data-case="${esc(c.id)}"><strong>${esc(c.id)}</strong><span>${esc(c.title)}</span><span class="list-status" data-status="${status}">${status} · ${qs.length} questions</span><small>${esc(c.subject)} · ${esc(c.topic)}</small></button>`}).join('')||'<p>No matching scenarios.</p>';$('scenario-library-list').querySelectorAll('button').forEach(b=>b.onclick=()=>ScenarioEditor.select(b.dataset.case));}
 function renderPreview(){const state=ScenarioEditor.state(),c=state.cases.find(c=>c.id===state.selected),q=previewQuestions[previewIndex],rich=t=>window.RichText?.render(t||'')||esc(t||'').replace(/\n/g,'<br>');$('scenario-preview-content').innerHTML=`<h3>${esc(c.id)} · ${esc(c.title)}</h3>`+['history','examination','laboratory'].filter(k=>c[k]).map(k=>`<section><h4>${{history:'History',examination:'Physical examination',laboratory:'Laboratory findings'}[k]}</h4>${rich(c[k])}</section>`).join('')+previewQuestions.slice(0,previewIndex+1).filter(x=>x.additional_findings).map(x=>`<section><h4>Additional findings · ${String.fromCharCode(64+x.case_order)}</h4>${rich(x.additional_findings)}</section>`).join('')+`<hr><h3>Question ${previewIndex+1} of ${previewQuestions.length}</h3>${rich(q.text)}${q.image?`<img class="scenario-preview-image" src="${esc(q.image)}" alt="Question picture">`:''}`+(q.choices||[]).map(o=>`<label class="preview-choice"><input type="${q.type==='multi'?'checkbox':'radio'}" name="scenario-preview-choice"> ${esc(o.id)} · ${rich(o.text)}</label>`).join('')+(q.type==='range'?'<label>Your answer<input type="number" step="any"></label>':'')+`<section id="preview-explanation" hidden><h4>Feedback</h4>${rich(q.explanation)||'No explanation provided.'}</section>`;$('preview-back').disabled=previewIndex===0;$('preview-next').disabled=true;$('preview-reveal').disabled=false;}
 window.addEventListener('question-workflow',()=>queueMicrotask(init));window.addEventListener('scenario-update',()=>queueMicrotask(update));if(window.ScenarioEditor)queueMicrotask(init);
})();
